const fs = require('fs');
const path = require('path');

const srcDir = 'E:\\GDM_LIVE_RADIO\\Minhas_Musicas';
const dstDir = 'E:\\GDM_LIVE_RADIO\\frontend\\public\\audio';

const files = fs.readdirSync(srcDir);

// Find tracks
const targets = [
  { filter: (f) => f.includes('Cruz') && f.includes('v1'), out: '01-a-cruz-e-o-sacrificio.mp3', title: 'A Cruz e o Sacrifício de Jesus' },
  { filter: (f) => f.includes('Dan') && f.includes('v1'), out: '02-a-danca-dos-redimidos.mp3', title: 'A Dança dos Redimidos' },
  { filter: (f) => f.includes('Luz Que Veio') && f.includes('musica 1'), out: '03-a-luz-que-veio-ao-mundo.mp3', title: 'A Luz Que Veio ao Mundo' },
  { filter: (f) => f.includes('Rocha') && f.includes('v1'), out: '04-a-rocha-mais-alta.mp3', title: 'A Rocha Mais Alta' },
  { filter: (f) => f.includes('Gl') && f.includes('v1'), out: '05-a-gloria-da-ultima-casa.mp3', title: 'A Glória da Última Casa' },
  { filter: (f) => f.includes('Bendize') && f.includes('v1'), out: '06-bendize-o-minha-alma.mp3', title: 'Bendize, Ó Minha Alma' }
];

const playlist = [];

for (const t of targets) {
  const match = files.find(t.filter);
  if (match) {
    const srcPath = path.join(srcDir, match);
    const dstPath = path.join(dstDir, t.out);
    fs.copyFileSync(srcPath, dstPath);
    const stat = fs.statSync(dstPath);
    console.log(`Copied ${match} -> ${t.out} (${stat.size} bytes)`);
    playlist.push({
      id: t.out,
      title: t.title,
      artist: 'Graça Digital (GDM)',
      album: 'Louvores de Fé & Esperança',
      url: `/audio/${t.out}`,
      coverUrl: '/images/player-album-art.jpg'
    });
  } else {
    console.log(`Could not find match for ${t.title}`);
  }
}

// Write the playlist manifest file for frontend
const tsContent = `// Autogenerated Web Playlist manifest for GDM Live Radio
export interface WebTrack {
  id: string;
  title: string;
  artist: string;
  album: string;
  url: string;
  coverUrl: string;
}

export const GDM_WEB_PLAYLIST: WebTrack[] = ${JSON.stringify(playlist, null, 2)};
`;

fs.writeFileSync('E:\\GDM_LIVE_RADIO\\frontend\\src\\config\\webPlaylist.ts', tsContent);
console.log('webPlaylist.ts created with', playlist.length, 'tracks.');
